actions.script:
            const dayOf = (value) => { if (value == null || value === '') return ''; const text = String(value); return /^-?\d+$/.test(text) ? new Date(Number(text)).toISOString().slice(0, 10) : text.slice(0, 10) }
capacityList = []
            const dayNum = (text) => Math.floor(Date.parse(String(text).slice(0, 10) + 'T00:00:00Z') / 86400000)
            const dayText = (num) => new Date(num * 86400000).toISOString().slice(0, 10)
            const isoDayOf = (text) => { const js = new Date(String(text).slice(0, 10) + 'T12:00:00Z').getUTCDay(); return js === 0 ? 7 : js }
            const first = Number(weekStart) >= 1 && Number(weekStart) <= 7 ? Number(weekStart) : 1
            const weekOf = (text) => dayText(dayNum(text) - ((isoDayOf(text) - first + 7) % 7))
            const toMillis = (value) => {
                if (value == null || value === '') return null
                if (typeof value === 'number') return value
                const text = String(value)
                if (/^-?\d+$/.test(text)) return Number(text)
                const parsed = Date.parse(text)
                return Number.isNaN(parsed) ? null : parsed
            }
            const dayStartMs = (text) => toMillis(ec.l10n.parseTimestamp(text + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'))
            const round = (value) => Math.round(value * 100) / 100
            const fromText = dayOf(fromDate || '')
            const thruText = dayOf(thruDate || '')
            if (!/^\d{4}-\d{2}-\d{2}$/.test(fromText) || !/^\d{4}-\d{2}-\d{2}$/.test(thruText)) { ec.message.addError(ec.l10n.localize('Capacity needs days as yyyy-MM-dd')); return }
            if (dayNum(thruText) < dayNum(fromText)) { ec.message.addError(ec.l10n.localize('Capacity needs the last day on or after the first')); return }
            if (dayNum(thruText) - dayNum(fromText) > 400) { ec.message.addError(ec.l10n.localize('Capacity covers at most 400 days')); return }
            const days = []
            for (let num = dayNum(fromText); num <= dayNum(thruText); num++) days.push(dayText(num))
            const starts = days.map(dayStartMs)
            const endMs = dayStartMs(dayText(dayNum(thruText) + 1))
            const dayIndexOf = (millis) => {
                // the day a moment is in: the last day start at or before it
                let low = 0, high = starts.length - 1, found = -1
                while (low <= high) { const mid = (low + high) >> 1; if (starts[mid] <= millis) { found = mid; low = mid + 1 } else high = mid - 1 }
                return found
            }
            // the hours of each day an interval covers
            const spread = (startMs, stopMs, into) => {
                if (stopMs <= starts[0] || startMs >= endMs) return
                for (let i = Math.max(0, dayIndexOf(startMs)); i < days.length; i++) {
                    const dayStart = starts[i]
                    const dayEnd = i + 1 < starts.length ? starts[i + 1] : endMs
                    if (dayStart >= stopMs) break
                    const overlap = Math.min(stopMs, dayEnd) - Math.max(startMs, dayStart)
                    if (overlap > 0) into[i] += overlap / 3600000
                }
            }
            const parties = Array.from(new Set((partyIdList != null ? Array.from(partyIdList) : []).concat(partyId ? [partyId] : []).filter((id) => id)))
            const policies = {}
            const holidaysByOrg = {}
            const policyOf = (person) => {
                if (policy != null && organizationPartyId) return {policy: policy, organizationPartyId: organizationPartyId}
                const key = person || '_'
                if (!policies[key]) {
                    const out = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetPolicy').parameters(person ? {partyId: person}
                            : (organizationPartyId ? {organizationPartyId: organizationPartyId} : {})).call() || {}
                    policies[key] = {policy: policy || out.policy || {dayHours: 8, workDays: [1, 2, 3, 4, 5]}, organizationPartyId: organizationPartyId || out.organizationPartyId || null}
                }
                return policies[key]
            }
            const holidaysOf = (orgId) => {
                if (!orgId) return {}
                if (!holidaysByOrg[orgId]) {
                    holidaysByOrg[orgId] = {}
                    try {
                        for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('purposeEnumId', 'WepHoliday').condition('ownerPartyId', orgId)
                                .condition('allDayStart', 'in', days).disableAuthz().list())
                            holidaysByOrg[orgId][dayOf(row.allDayStart)] = row.workEffortName || ec.l10n.localize('Holiday')
                    } catch (err) { ec.logger.error(`Capacity: the holidays of ${orgId} were not read, none marked: ${err}`) }
                }
                return holidaysByOrg[orgId]
            }
            const calendar = (person, typeId) => {
                const out = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters({partyId: person, start: fromText,
                    end: dayText(dayNum(thruText) + 1), includeAllUsers: false, excludeCancelled: true, workEffortTypeEnumIds: [typeId], titleGString: '-'}).call()
                if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
                return Array.from(out?.eventList || [])
            }
            const entryOf = (person) => {
                const {policy: thePolicy, organizationPartyId: orgId} = policyOf(person)
                const workDays = Array.from(thePolicy.workDays || [1, 2, 3, 4, 5]).map(Number)
                const dayHours = Number(thePolicy.dayHours || 8)
                let base = days.map((day) => workDays.includes(isoDayOf(day)) ? dayHours : 0)
                let source = 'policy'
                const leave = days.map(() => 0)
                if (person) {
                    ec.message.pushErrors()
                    try {
                        const cf = ec.entity.conditionFactory
                        const hasAvailable = ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('workEffortTypeEnumId', 'WetAvailable')
                                .condition('partyId', person).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).count() > 0
                                || ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetAvailable').condition('ownerPartyId', person).count() > 0
                        if (hasAvailable) {
                            const hours = days.map(() => 0)
                            for (const event of calendar(person, 'WetAvailable')) {
                                const startMs = toMillis(event.startMillis)
                                const stopMs = event.endMillis != null ? toMillis(event.endMillis) : startMs + 3600000
                                if (startMs != null && stopMs > startMs) spread(startMs, stopMs, hours)
                            }
                            base = hours.map((value) => Math.min(24, round(value)))
                            source = 'available'
                        }
                    } catch (err) {
                        ec.logger.error(`Capacity of ${person}: the working hours were not read, the policy's apply: ${err && err.message ? err.message : err}`)
                    } finally { ec.message.clearErrors(); ec.message.popErrors() }
                    ec.message.pushErrors()
                    try {
                        for (const event of calendar(person, 'WetTimeOff')) {
                            if (event.allDay) {
                                const lastNum = event.end ? dayNum(event.end) - 1 : dayNum(event.start)
                                for (let num = dayNum(event.start); num <= lastNum; num++) {
                                    const index = num - dayNum(fromText)
                                    if (index >= 0 && index < days.length) leave[index] = 24
                                }
                            } else {
                                const startMs = toMillis(event.startMillis)
                                const stopMs = event.endMillis != null ? toMillis(event.endMillis) : startMs + 3600000
                                if (startMs != null && stopMs > startMs) spread(startMs, stopMs, leave)
                            }
                        }
                    } catch (err) {
                        ec.logger.error(`Capacity of ${person}: the leave was not read, none taken off: ${err && err.message ? err.message : err}`)
                    } finally { ec.message.clearErrors(); ec.message.popErrors() }
                }
                const holidays = holidaysOf(orgId)
                const dayList = days.map((day, i) => {
                    const holiday = holidays[day] || null
                    const off = holiday ? base[i] : Math.min(base[i], round(leave[i]))
                    return {day: day, isoDay: isoDayOf(day), weekStart: weekOf(day), base: base[i], holiday: holiday, leave: holiday ? 0 : off,
                        capacity: round(Math.max(0, base[i] - off))}
                })
                const weeks = new Map()
                for (const entry of dayList) {
                    let week = weeks.get(entry.weekStart)
                    if (!week) { week = {weekStart: entry.weekStart, base: 0, holidayHours: 0, leaveHours: 0, capacity: 0, workDays: 0}; weeks.set(entry.weekStart, week) }
                    week.base += entry.base
                    if (entry.holiday) week.holidayHours += entry.base
                    week.leaveHours += entry.leave
                    week.capacity += entry.capacity
                    if (entry.capacity > 0) week.workDays += 1
                }
                const weekList = Array.from(weeks.values()).map((week) => Object.assign(week, {base: round(week.base), holidayHours: round(week.holidayHours),
                    leaveHours: round(week.leaveHours), capacity: round(week.capacity)}))
                return {partyId: person || null, source: source, organizationPartyId: orgId, dayList: dayList, weekList: weekList,
                    base: round(dayList.reduce((sum, entry) => sum + entry.base, 0)), capacity: round(dayList.reduce((sum, entry) => sum + entry.capacity, 0))}
            }
            const wasDisabled = ec.artifactExecution.disableAuthz()
            try {
                if (!parties.length) { capacityList.push(entryOf(null)); return }
                for (const person of parties) {
                    try { capacityList.push(entryOf(person)) } catch (err) {
                        ec.logger.error(`Capacity of ${person} not computed: ${err && err.message ? err.message : err}`)
                    }
                }
            } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

            const dayOf = (value) => { if (value == null || value === '') return ''; const text = String(value); return /^-?\d+$/.test(text) ? new Date(Number(text)).toISOString().slice(0, 10) : text.slice(0, 10) }
weekHours = {}
            let sum = 0
            const from = dayOf(allocation.fromDate || '')
            const thru = dayOf(allocation.thruDate || '')
            const perWeek = allocation.hoursPerWeek != null && allocation.hoursPerWeek !== '' ? Number(String(allocation.hoursPerWeek)) : null
            const percent = allocation.allocationPercent != null && allocation.allocationPercent !== '' ? Number(String(allocation.allocationPercent)) : null
            const baseOfWeek = {}
            for (const day of Array.from(capacity.dayList || [])) baseOfWeek[day.weekStart] = (baseOfWeek[day.weekStart] || 0) + Number(day.base || 0)
            for (const day of Array.from(capacity.dayList || [])) {
                if (!(weekHours[day.weekStart] >= 0)) weekHours[day.weekStart] = 0
                if ((from && day.day < from) || (thru && day.day > thru)) continue
                const base = Number(day.base || 0)
                if (!(base > 0)) continue
                let hours = 0
                if (percent != null) hours = base * percent / 100
                else if (perWeek != null && baseOfWeek[day.weekStart] > 0) hours = perWeek * base / baseOfWeek[day.weekStart]
                weekHours[day.weekStart] += hours
                sum += hours
            }
            for (const key of Object.keys(weekHours)) weekHours[key] = Math.round(weekHours[key] * 100) / 100
            total = Math.round(sum * 100) / 100

canView = false; canRequest = false; canApprove = false; canChange = false; canCancel = false; allocation = null; project = null
const L = (text) => ec.l10n.localize(text)
isApprover = !!ec.user.userId && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('ALLOCATION_APPROVE'))
let row = null
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (workEffortAllocationId) {
        row = ec.entity.find('mantle.work.effort.WorkEffortAllocation').condition('workEffortAllocationId', workEffortAllocationId).one()
        if (row) rootWorkEffortId = row.rootWorkEffortId
    }
    const projectRow = rootWorkEffortId ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', rootWorkEffortId).one() : null
    if (projectRow && projectRow.workEffortTypeEnumId === 'WetProject' && (!workEffortAllocationId || row)) {
        const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
        const all = !!vis.allProjects
        canView = all || Array.from(vis.visibleProjectIds || []).includes(rootWorkEffortId)
        if (canView) {
            project = projectRow.getMap()
            const manages = all || Array.from(vis.managedProjectIds || []).includes(rootWorkEffortId)
            canApprove = isApprover
            canRequest = manages || isApprover
            if (row) {
                allocation = row.getMap()
                const open = row.statusId === 'WealRequested' || row.statusId === 'WealAllocated'
                const mine = row.requestedByUserId === ec.user.userId
                canChange = open && (isApprover || (row.statusId === 'WealRequested' && mine && canRequest))
                canCancel = canChange
            }
        }
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (need === 'none') return
if (!canView) { ec.message.addError(workEffortAllocationId ? ec.resource.expand('Allocation ${workEffortAllocationId} is not available', '', {workEffortAllocationId})
        : ec.resource.expand('Project ${rootWorkEffortId} is not available', '', {rootWorkEffortId: rootWorkEffortId || ''})); return }
if (need === 'request' && !canRequest) ec.message.addError(L('Only the managers of the project request allocations on it'))
else if (need === 'approve' && !canApprove) ec.message.addError(L('Only those who approve allocations decide them'))
else if (need === 'change' && !canChange) ec.message.addError(L('You may not change this allocation'))

const L = (text) => ec.l10n.localize(text)
const target = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).disableAuthz().one()
if (!target) { ec.message.addError(ec.resource.expand('Project ${workEffortId} is not available', '', {workEffortId})); return }
const root = target.workEffortTypeEnumId === 'WetProject' ? target.workEffortId : target.rootWorkEffortId
if (!root) { ec.message.addError(L('An allocation is on a project or a work item of one')); return }
const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({rootWorkEffortId: root, need: 'request'}).call() || {}
if (ec.message.hasError()) return
const checked = ec.service.sync().name('mantle.work.ResourceServices.check#AllocationFields').parameters({partyId: partyId || null,
    roleTypeId: roleTypeId || null, skillTypeEnumId: skillTypeEnumId || null, fromDate: fromDate, thruDate: thruDate,
    hoursPerWeek: hoursPerWeek, allocationPercent: allocationPercent}).call() || {}
if (ec.message.hasError()) return
statusId = access.canApprove && !request ? 'WealAllocated' : 'WealRequested'
const now = ec.user.nowTimestamp
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    workEffortAllocationId = ec.service.sync().name('create#mantle.work.effort.WorkEffortAllocation').parameters({workEffortId: workEffortId,
        rootWorkEffortId: root, partyId: partyId || null, roleTypeId: roleTypeId || null, emplPositionClassId: emplPositionClassId || null,
        skillTypeEnumId: skillTypeEnumId || null, fromDate: checked.fromDay, thruDate: checked.thruDay,
        hoursPerWeek: checked.allocationPercent != null ? null : checked.hoursPerWeek, allocationPercent: checked.allocationPercent,
        statusId: statusId, requestedByUserId: ec.user.userId, requestedDate: now, reviewedByUserId: statusId === 'WealAllocated' ? ec.user.userId : null,
        reviewedDate: statusId === 'WealAllocated' ? now : null, comments: comments || null}).call()?.workEffortAllocationId
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (ec.message.hasError() || !workEffortAllocationId) return
if (partyId) ec.service.sync().name('mantle.work.ResourceServices.add#AllocationMember').parameters({workEffortAllocationId: workEffortAllocationId}).call()
if (statusId === 'WealRequested') ec.service.sync().name('mantle.work.ResourceServices.notify#Allocation').parameters({workEffortAllocationId: workEffortAllocationId,
    change: 'requested'}).call()
message = statusId === 'WealAllocated' ? L('Allocated') : L('Allocation requested')

const L = (text) => ec.l10n.localize(text)
const dayOf = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    if (/^\d{4}-\d{2}-\d{2}/.test(text) && !/^\d+$/.test(text)) return text.slice(0, 10)
    const millis = /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
    if (Number.isNaN(millis)) return null
    // a date field reaches a script as the epoch millis of its UTC midnight; a time stamp is taken as its day here
    return millis % 86400000 === 0 ? new Date(millis).toISOString().slice(0, 10) : ec.l10n.format(new Date(millis), 'yyyy-MM-dd')
}
if (!partyId && !roleTypeId && !skillTypeEnumId) { ec.message.addError(L('Name a person, or the role or skill of a placeholder to staff')); return }
if (partyId && !ec.entity.find('mantle.party.Person').condition('partyId', partyId).disableAuthz().one()) {
    ec.message.addError(ec.resource.expand('${partyId} is not a person', '', {partyId})); return }
if (roleTypeId && !ec.entity.find('mantle.party.RoleType').condition('roleTypeId', roleTypeId).useCache(true).disableAuthz().one()) {
    ec.message.addError(ec.resource.expand('${roleTypeId} is not a role', '', {roleTypeId})); return }
if (skillTypeEnumId && !ec.entity.find('moqui.basic.Enumeration').condition('enumId', skillTypeEnumId).condition('enumTypeId', 'SkillType').useCache(true).disableAuthz().one()) {
    ec.message.addError(ec.resource.expand('${skillTypeEnumId} is not a skill', '', {skillTypeEnumId})); return }
fromDay = dayOf(fromDate)
thruDay = dayOf(thruDate)
if (!fromDay || !thruDay) { ec.message.addError(L('An allocation needs its first and last days')); return }
if (thruDay < fromDay) { ec.message.addError(L('The last day is on or after the first')); return }
if ((Date.parse(thruDay + 'T00:00:00Z') - Date.parse(fromDay + 'T00:00:00Z')) / 86400000 > 731) { ec.message.addError(L('An allocation is at most two years long')); return }
const percent = allocationPercent == null ? null : Number(String(allocationPercent))
const hours = hoursPerWeek == null ? null : Number(String(hoursPerWeek))
if (percent != null) {
    if (!(percent > 0 && percent <= 100)) { ec.message.addError(L('A percent of capacity is above 0 and at most 100')); return }
    allocationPercent = percent; hoursPerWeek = null
} else {
    if (!(hours > 0 && hours <= 168)) { ec.message.addError(L('Hours a week are above 0 and at most 168')); return }
    hoursPerWeek = hours; allocationPercent = null
}

added = false
ec.message.pushErrors()
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const row = ec.entity.find('mantle.work.effort.WorkEffortAllocation').condition('workEffortAllocationId', workEffortAllocationId).one()
    if (!row || !row.partyId || !row.rootWorkEffortId) return
    const current = ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', row.rootWorkEffortId).condition('partyId', row.partyId)
            .conditionDate('fromDate', 'thruDate', null).count()
    if (current > 0) return
    const inGroup = row.roleTypeId ? ec.entity.find('mantle.party.RoleGroupMember').condition('roleGroupEnumId', 'RgpProject')
            .condition('roleTypeId', row.roleTypeId).useCache(true).one() : null
    ec.service.sync().name('mantle.work.WorkEffortServices.add#WorkEffortParty').parameters({workEffortId: row.rootWorkEffortId, partyId: row.partyId,
        roleTypeId: inGroup ? row.roleTypeId : 'Assignee', statusId: 'WeptAssigned'}).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    added = true
} catch (err) {
    ec.logger.error(`Allocation ${workEffortAllocationId}: the person was not added to the project: ${err && err.message ? err.message : err}`)
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
    ec.message.clearErrors(); ec.message.popErrors()
}

service.description:
Changes an allocation's days, hours a week or percent, role, skill and comments (a value not given is kept;
            hoursPerWeek replaces a percent and allocationPercent hours). By an approver, or by its requester while it is
            requested. A drag on the team planner calls it.

actions.script:
const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({workEffortAllocationId: workEffortAllocationId,
    need: 'change'}).call() || {}
if (ec.message.hasError()) return
const current = access.allocation
const usePercent = allocationPercent != null || (hoursPerWeek == null && current.allocationPercent != null)
const checked = ec.service.sync().name('mantle.work.ResourceServices.check#AllocationFields').parameters({partyId: current.partyId || null,
    roleTypeId: roleTypeId != null ? (roleTypeId || null) : current.roleTypeId, skillTypeEnumId: skillTypeEnumId != null ? (skillTypeEnumId || null) : current.skillTypeEnumId,
    fromDate: fromDate || current.fromDate, thruDate: thruDate || current.thruDate,
    hoursPerWeek: usePercent ? null : (hoursPerWeek != null ? hoursPerWeek : current.hoursPerWeek),
    allocationPercent: usePercent ? (allocationPercent != null ? allocationPercent : current.allocationPercent) : null}).call() || {}
if (ec.message.hasError()) return
const fields = {workEffortAllocationId: workEffortAllocationId, fromDate: checked.fromDay, thruDate: checked.thruDay,
    hoursPerWeek: checked.hoursPerWeek, allocationPercent: checked.allocationPercent}
if (roleTypeId != null) fields.roleTypeId = roleTypeId || null
if (skillTypeEnumId != null) fields.skillTypeEnumId = skillTypeEnumId || null
if (comments != null) fields.comments = comments || null
const wasDisabled = ec.artifactExecution.disableAuthz()
try { ec.service.sync().name('update#mantle.work.effort.WorkEffortAllocation').parameters(fields).call() }
finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (!ec.message.hasError()) message = ec.l10n.localize('Allocation changed')

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({workEffortAllocationId: workEffortAllocationId,
    need: 'change'}).call() || {}
if (ec.message.hasError()) return
const current = access.allocation
if (current.partyId && current.statusId !== 'WealRequested') { ec.message.addError(L('An allocated person is changed by cancelling the allocation and making another')); return }
if (!ec.entity.find('mantle.party.Person').condition('partyId', partyId).disableAuthz().one()) {
    ec.message.addError(ec.resource.expand('${partyId} is not a person', '', {partyId})); return }
statusId = current.statusId
const fields = {workEffortAllocationId: workEffortAllocationId, partyId: partyId}
if (access.canApprove && approve && current.statusId === 'WealRequested') {
    statusId = 'WealAllocated'
    Object.assign(fields, {statusId: statusId, reviewedByUserId: ec.user.userId, reviewedDate: ec.user.nowTimestamp})
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try { ec.service.sync().name('update#mantle.work.effort.WorkEffortAllocation').parameters(fields).call() }
finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (ec.message.hasError()) return
ec.service.sync().name('mantle.work.ResourceServices.add#AllocationMember').parameters({workEffortAllocationId: workEffortAllocationId}).call()
if (statusId === 'WealAllocated' && current.statusId === 'WealRequested') ec.service.sync().name('mantle.work.ResourceServices.notify#Allocation')
        .parameters({workEffortAllocationId: workEffortAllocationId, change: 'approved'}).call()
const person = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).disableAuthz().one()
const name = person ? [person.firstName, person.lastName].filter((part) => part).join(' ') || partyId : partyId
message = statusId === 'WealAllocated' && current.statusId === 'WealRequested' ? ec.resource.expand('${name} staffed and allocated', '', {name})
        : ec.resource.expand('${name} staffed', '', {name})

const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({workEffortAllocationId: workEffortAllocationId,
    need: 'approve'}).call() || {}
if (ec.message.hasError()) return
if (access.allocation.statusId !== 'WealRequested') { ec.message.addError(ec.l10n.localize('Only a requested allocation is approved')); return }
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    ec.service.sync().name('update#mantle.work.effort.WorkEffortAllocation').parameters({workEffortAllocationId: workEffortAllocationId,
        statusId: 'WealAllocated', reviewedByUserId: ec.user.userId, reviewedDate: ec.user.nowTimestamp}).call()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (ec.message.hasError()) return
ec.service.sync().name('mantle.work.ResourceServices.add#AllocationMember').parameters({workEffortAllocationId: workEffortAllocationId}).call()
ec.service.sync().name('mantle.work.ResourceServices.notify#Allocation').parameters({workEffortAllocationId: workEffortAllocationId, change: 'approved'}).call()
message = ec.l10n.localize('Allocation approved')

const L = (text) => ec.l10n.localize(text)
const text = String(reason || '').trim()
if (!text) { ec.message.addError(L('Say why the allocation is rejected')); return }
