                        const weeksOut = weekList.map((week) => {
                            const cap = Array.from(capacity.weekList || []).find((one) => one.weekStart === week.weekStart) || {base: 0, capacity: 0, holidayHours: 0, leaveHours: 0}
                            return {weekStart: week.weekStart, base: cap.base, capacity: cap.capacity, holidayHours: cap.holidayHours, leaveHours: cap.leaveHours,
                                allocated: 0, requested: 0, assigned: 0, logged: 0, load: 0, over: false, utilization: null}
                        })
                        const byWeek = {}
                        for (const week of weeksOut) byWeek[week.weekStart] = week
                        const allocationList = allocRows.filter((row) => row.partyId === person).map((row) => allocEntry(row, capacity))
                        for (const alloc of allocationList) for (const [weekStart, hours] of Object.entries(alloc.weekHours)) {
                            const week = byWeek[weekStart]
                            if (!week) continue
                            if (alloc.statusId === 'WealAllocated') week.allocated += hours; else week.requested += hours
                        }
                        // assigned work: the open items the person is an assignee of, their remaining hours spread over the working days
                        let undatedHours = 0
                        const assignedIds = Array.from(new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('partyId', person)
                                .condition('roleTypeId', 'Assignee').conditionDate('fromDate', 'thruDate', null)
                                .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).selectField('workEffortId').list())
                                .map((row) => row.workEffortId)))
                        const workingIso = new Set(Array.from(capacity.dayList || []).filter((day) => day.base > 0).map((day) => day.isoDay))
                        if (!workingIso.size) [1, 2, 3, 4, 5].forEach((day) => workingIso.add(day))
                        const capacityOfDay = {}
                        for (const day of Array.from(capacity.dayList || [])) capacityOfDay[day.day] = day.capacity
                        if (assignedIds.length) {
                            const items = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', assignedIds)
                                    .condition('workEffortTypeEnumId', 'WetTask').condition('statusId', 'not-in', doneStatuses).list())
                            for (const item of items) {
                                const remaining = Number(String(item.remainingWorkTime ?? item.estimatedWorkTime ?? 0))
                                if (!(remaining > 0)) continue
                                const assignees = ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', item.workEffortId).condition('roleTypeId', 'Assignee')
                                        .conditionDate('fromDate', 'thruDate', null).count() || 1
                                const share = remaining / assignees
                                if (!item.estimatedCompletionDate) { undatedHours += share; continue }
                                const due = ec.l10n.format(item.estimatedCompletionDate, 'yyyy-MM-dd')
                                const startAt = item.estimatedStartDate ? ec.l10n.format(item.estimatedStartDate, 'yyyy-MM-dd') : today
                                const from = startAt > today ? startAt : today
                                if (due < today) { if (byWeek[currentWeek]) byWeek[currentWeek].assigned += share; continue }
                                const days = []
                                for (let num = dayNum(from); num <= dayNum(due) && days.length < 800; num++) {
                                    const text = dayText(num)
                                    const inRange = text in capacityOfDay
                                    if (inRange ? capacityOfDay[text] > 0 : workingIso.has(isoDayOf(text))) days.push(text)
                                }
                                if (!days.length) { const week = byWeek[weekOfDay(due)]; if (week) week.assigned += share; continue }
                                const perDay = share / days.length
                                for (const day of days) { const week = byWeek[weekOfDay(day)]; if (week) week.assigned += perDay }
                            }
                        }
                        // logged time by week
                        const fromStamp = ec.l10n.parseTimestamp(firstDay + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
                        const thruStamp = ec.l10n.parseTimestamp(dayText(dayNum(lastDay) + 1) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
                        for (const entry of ec.entity.find('mantle.work.time.TimeEntry').condition('partyId', person).condition('fromDate', 'greater-equals', fromStamp)
                                .condition('fromDate', 'less-than', thruStamp).selectField('fromDate').selectField('hours').list()) {
                            const week = byWeek[weekOfDay(ec.l10n.format(entry.fromDate, 'yyyy-MM-dd'))]
                            if (week) week.logged += Number(String(entry.hours ?? 0))
                        }
                        for (const week of weeksOut) {
                            week.allocated = round(week.allocated); week.requested = round(week.requested); week.assigned = round(week.assigned); week.logged = round(week.logged)
                            const most = Math.max(week.allocated, week.assigned)
                            week.load = week.capacity > 0 ? round(most / week.capacity) : (most > 0 ? 9.99 : 0)
                            week.over = most > week.capacity + 0.01
                            week.utilization = week.capacity > 0 && week.weekStart <= currentWeek ? round(week.logged / week.capacity) : null
                        }
                        const roles = roleOfParty[person] || {}
                        const mainRole = Object.keys(roles).sort((a, b) => roles[b] - roles[a] || a.localeCompare(b))[0] || null
                        const account = ec.entity.find('moqui.security.UserAccount').condition('partyId', person).selectField('userId').list()[0]
                        plan.personList.push({partyId: person, name: nameOf(person), userId: account?.userId || null, roleTypeId: mainRole, roleText: mainRole ? roleText(mainRole) : '',
                            skillList: skillRows.filter((row) => row.partyId === person).map((row) => ({skillTypeEnumId: row.skillTypeEnumId, label: enumText(row.skillTypeEnumId),
                                rating: row.rating != null ? Number(String(row.rating)) : (row.skillLevel != null ? Number(String(row.skillLevel)) : null)}))
                                .sort((a, b) => (b.rating || 0) - (a.rating || 0) || a.label.localeCompare(b.label)),
                            source: capacity.source, weekList: weeksOut, allocationList: allocationList, undatedHours: round(undatedHours)})
                    } catch (err) {
                        plan.failedPartyIds.push(person)
                        ec.logger.error(`Team plan: ${person} left out: ${err && err.message ? err.message : err}`)
                    } finally { ec.message.clearErrors(); ec.message.popErrors() }
                }
                if (includePlaceholders) {
                    for (const row of allocRows.filter((one) => !one.partyId && sees(one.rootWorkEffortId))) {
                        if (rootWorkEffortId && row.rootWorkEffortId !== rootWorkEffortId) continue
                        if (roleTypeId && row.roleTypeId !== roleTypeId) continue
                        if (skillTypeEnumId && row.skillTypeEnumId !== skillTypeEnumId) continue
                        if (teamPartyId) continue
                        plan.placeholderList.push(allocEntry(row, standard))
                    }
                }
                plan.projectList = Array.from(usedProjects).map((id) => ({workEffortId: id, workEffortName: projectNames[id] || id}))
                        .sort((a, b) => a.workEffortName.localeCompare(b.workEffortName))
                if (withOptions) {
                    const roleIds = Array.from(new Set(memberRows.map((row) => row.roleTypeId)))
                    const skillTypes = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'SkillType').orderBy('sequenceNum').orderBy('description').useCache(true).list())
                    const teamIds = Array.from(new Set(Array.from(ec.entity.find('mantle.party.PartyRole').condition('roleTypeId', 'OrgTeam').selectField('partyId').limit(200).list())
                            .map((row) => row.partyId)))
                    plan.options = {
                        roleOptions: roleIds.map((id) => ({value: id, label: roleText(id)})).sort((a, b) => a.label.localeCompare(b.label)),
                        skillOptions: skillTypes.map((row) => ({value: row.enumId, label: row.description || row.enumId})),
                        teamOptions: teamIds.map((id) => ({value: id, label: nameOf(id)})).sort((a, b) => a.label.localeCompare(b.label)),
                        projectOptions: projectRows.map((row) => ({value: row.workEffortId, label: row.workEffortName + ' (' + row.workEffortId + ')'}))
                            .sort((a, b) => a.label.localeCompare(b.label))
                    }
                }
            } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

            const dayOf = (value) => { if (value == null || value === '') return ''; const text = String(value); return /^-?\d+$/.test(text) ? new Date(Number(text)).toISOString().slice(0, 10) : text.slice(0, 10) }
candidateList = []
            const round = (value) => Math.round(value * 100) / 100
            if (workEffortAllocationId) {
                const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({workEffortAllocationId: workEffortAllocationId,
                    need: 'view'}).call() || {}
                if (ec.message.hasError()) return
                allocation = access.allocation
            } else {
                const checked = ec.service.sync().name('mantle.work.ResourceServices.check#AllocationFields').parameters({roleTypeId: roleTypeId || null,
                    skillTypeEnumId: skillTypeEnumId || null, fromDate: fromDate, thruDate: thruDate, hoursPerWeek: hoursPerWeek, allocationPercent: allocationPercent}).call() || {}
                if (ec.message.hasError()) return
                allocation = {fromDate: checked.fromDay, thruDate: checked.thruDay, hoursPerWeek: checked.hoursPerWeek, allocationPercent: checked.allocationPercent,
                    roleTypeId: roleTypeId || null, skillTypeEnumId: skillTypeEnumId || null}
            }
            const role = allocation.roleTypeId || null
            const skill = allocation.skillTypeEnumId || null
            const dayNum = (text) => Math.floor(Date.parse(String(text).slice(0, 10) + 'T00:00:00Z') / 86400000)
            const dayText = (num) => new Date(num * 86400000).toISOString().slice(0, 10)
            const isoDayOf = (text) => { const js = new Date(String(text).slice(0, 10) + 'T12:00:00Z').getUTCDay(); return js === 0 ? 7 : js }
            const fromDay = dayOf(allocation.fromDate)
            const thruDay = dayOf(allocation.thruDate)
            const firstDay = dayText(dayNum(fromDay) - (isoDayOf(fromDay) - 1))
            const lastDay = dayText(dayNum(thruDay) + (7 - isoDayOf(thruDay)))
            const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
            const all = !!vis.allProjects
            const visible = new Set(Array.from(vis.visibleProjectIds || []))
            const showRates = !!withRates && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('TIME_ENTRY_RATE'))
            const wasDisabled = ec.artifactExecution.disableAuthz()
            try {
                const pool = new Set(Array.from(ec.service.sync().name('mantle.work.TimesheetServices.get#TimeKeepers').call()?.partyIdList || []))
                const skillRows = {}
                if (skill) for (const row of ec.entity.find('mantle.humanres.ability.PartySkill').condition('skillTypeEnumId', skill).list()) {
                    pool.add(row.partyId); skillRows[row.partyId] = row }
                const roleHolders = new Set()
                if (role) for (const row of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('roleTypeId', role).conditionDate('fromDate', 'thruDate', null)
                        .selectField('partyId').list()) { roleHolders.add(row.partyId); pool.add(row.partyId) }
                let people = pool.size ? Array.from(ec.entity.find('mantle.party.Person').condition('partyId', 'in', Array.from(pool)).selectField('partyId').list()).map((row) => row.partyId) : []
                if (allocation.partyId) people = people.filter((id) => id !== allocation.partyId || allocation.statusId === 'WealRequested')
                if (!people.length) return
                if (people.length > 200) people = people.slice(0, 200)
                const capacities = {}
                for (const entry of Array.from(ec.service.sync().name('mantle.work.ResourceServices.get#PartyCapacity').parameters({partyIdList: people,
                        fromDate: firstDay, thruDate: lastDay}).call()?.capacityList || [])) capacities[entry.partyId] = entry
                ec.message.clearErrors()
                const allocRows = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAllocation').condition('partyId', 'in', people)
                        .condition('statusId', 'equals', 'WealAllocated').condition('fromDate', 'less-equals', lastDay).condition('thruDate', 'greater-equals', firstDay).list())
                        .filter((row) => !allocation.workEffortAllocationId || row.workEffortAllocationId !== allocation.workEffortAllocationId)
                const weeksOf = (row, capacity) => ec.service.sync().name('mantle.work.ResourceServices.get#AllocationWeeks').parameters({allocation: row, capacity: capacity})
                        .call()?.weekHours || {}
                const nameOf = (partyId) => {
                    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
                    return party ? ([party.firstName, party.lastName].filter((part) => part).join(' ') || party.organizationName || partyId) : partyId
                }
                const nowStamp = ec.user.nowTimestamp
                for (const person of people) {
                    try {
                        const capacity = capacities[person]
                        if (!capacity) continue
                        const need = weeksOf(allocation, capacity)
                        const taken = {}
                        for (const row of allocRows.filter((one) => one.partyId === person)) for (const [week, hours] of Object.entries(weeksOf(row.getMap(), capacity)))
                            taken[week] = (taken[week] || 0) + hours
                        let freeHours = 0, needHours = 0, shortWeeks = 0, minFree = null
                        for (const week of Array.from(capacity.weekList || [])) {
                            const needWeek = need[week.weekStart] || 0
                            if (!(needWeek > 0)) continue
                            const free = week.capacity - (taken[week.weekStart] || 0)
                            freeHours += Math.max(0, free)
                            needHours += needWeek
                            if (free + 0.01 < needWeek) shortWeeks++
                            if (minFree == null || free < minFree) minFree = free
                        }
                        const projects = Array.from(new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', person)
                                .condition('workEffortTypeEnumId', 'WetProject').condition('statusId', 'not-in', ['WeClosed', 'WeCancelled']).conditionDate('fromDate', 'thruDate', null)
                                .list()).filter((row) => row.isTemplate !== 'Y' && (all || visible.has(row.workEffortId))).map((row) => row.workEffortName || row.workEffortId))).sort()
                        const skillRow = skillRows[person]
                        const rating = skillRow ? Number(String(skillRow.rating ?? skillRow.skillLevel ?? 0)) : null
                        const entry = {partyId: person, name: nameOf(person), hasSkill: !!skillRow, skillRating: rating, hasRole: roleHolders.has(person),
                            fits: shortWeeks === 0 && needHours > 0, shortWeeks: shortWeeks, freeHours: round(freeHours), needHours: round(needHours),
                            minFreeWeek: minFree == null ? null : round(minFree), currentProjects: projects, costRate: null, costCurrencyUomId: null}
                        if (showRates) {
                            const rate = Array.from(ec.entity.find('mantle.humanres.rate.RateAmount').condition('partyId', person).condition('ratePurposeEnumId', 'RaprVendor')
                                    .condition('workEffortId', 'is-null', null).conditionDate('fromDate', 'thruDate', nowStamp).orderBy('-fromDate').limit(1).list())[0]
                            if (rate) { entry.costRate = Number(String(rate.rateAmount)); entry.costCurrencyUomId = rate.rateCurrencyUomId || null }
                        }
                        candidateList.push(entry)
                    } catch (err) {
                        ec.logger.error(`Staffing candidates: ${person} left out: ${err && err.message ? err.message : err}`)
                    }
                }
                const scoreOf = (one) => (one.fits ? 1000 : 0) + (one.hasSkill ? 200 + 10 * (one.skillRating || 0) : 0) + (one.hasRole ? 100 : 0)
                candidateList.sort((a, b) => scoreOf(b) - scoreOf(a) || b.freeHours - a.freeHours || a.name.localeCompare(b.name))
                candidateList = candidateList.slice(0, Math.max(1, Number(limit) || 20))
            } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
